insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_bhattarika','Bhattarika Temple & Mahanadi Gorge','Odisha','Cuttack','Temple','Bhattarika Temple is dramatically situated on the rocky bank of the Mahanadi River at Badamba. Dedicated to Goddess Bhattarika (form of Shakti), mythology holds that Lord Parashurama prayed here to regain his celestial power. The temple offers magnificent river gorge vistas.','20.4167','85.3333','needs_review','October – March','1',array['temple','river','gorge','nature','peaceful','day trip','hidden gem']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
