insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_barehipani','Barehipani & Joranda Waterfalls','Odisha','Mayurbhanj','Waterfall','Barehipani is India''s second highest waterfall, plunging 250 meters (820 feet) in two majestic tiers over a cliff face into a dense jungle gorge. Nearby stands Joranda Falls, a single vertical drop of 150 meters (490 feet). Both are located in the heart of Simlipal National Park.','21.9333','86.3833','needs_review','November – June','1',array['waterfall','highest waterfall','simlipal','nature','forest','must see']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
