insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_mandira_dam','Mandira Dam & Reservoir','Odisha','Sundargarh','Lake','Built across the Sankha river, Mandira Dam creates a sweeping lake surrounded by picturesque emerald hills. It serves as water supply to Rourkela Steel Plant and doubles as a premier leisure and boating retreat.','22.2858','84.6681','needs_review','October – March','1',array['dam','lake','boating','hills','sunset','peaceful']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
