insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_karlapat','Karlapat Wildlife Sanctuary & Jakham','Odisha','Kalahandi','Wildlife','Karlapat Wildlife Sanctuary covers 147 sq km of pristine dry deciduous and moist peninsular sal forest in the Eastern Ghats. Rich in wildlife, it is home to tigers, leopards, barking deer, wild dogs, and sizable elephant herds.','19.75','83.15','needs_review','November – April','2',array['wildlife','elephants','leopard','orchids','valley','eco tourism']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
