insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_subarnameru','Subarnameru Temple & Silk Weavers Village','Odisha','Subarnapur','Heritage','Subarnameru Temple on the banks of river Tel is dedicated to Lord Shiva. Local lore recounts that gold coins once showered upon this shrine, giving the town its name ''Subarnapur'' (City of Gold). Adjacent weaving clusters produce the GI-tagged Sonepuri and Bomkai silk sarees with intricate double-ikat motifs.','20.835','83.915','needs_review','October – March','1',array['temple','shiva','silk','handloom','bomkai','craft','heritage']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
